Here's a minimal debounce utility and two examples:

```javascript
// debounce.js
function debounce(fn, delay) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn(...args), delay);
  };
}
```

**Vanilla JavaScript:**
```javascript
const searchInput = document.querySelector('input[type="search"]');
const debouncedSearch = debounce(async (query) => {
  const response = await fetch(`/api/search?q=${query}`);
  const results = await response.json();
  updateResults(results);
}, 300);

searchInput.addEventListener('input', (e) => {
  debouncedSearch(e.target.value);
});
```

**React:**
```javascript
import { useState } from 'react';

function SearchInput() {
  const [results, setResults] = useState([]);

  const debouncedSearch = debounce(async (query) => {
    if (!query) return;
    const response = await fetch(`/api/search?q=${query}`);
    const data = await response.json();
    setResults(data);
  }, 300);

  return (
    <>
      <input 
        type="search"
        onChange={(e) => debouncedSearch(e.target.value)}
        placeholder="Search..."
      />
      <ul>
        {results.map(r => <li key={r.id}>{r.name}</li>)}
      </ul>
    </>
  );
}
```

**Key points:**
- `300ms` delay typical for search; adjust as needed
- Previous timeout clears on each keystroke
- Vanilla: fire after keystroke stops
- React: works with event handlers; use `useEffect` + `useRef` if you need cleanup on unmount

